#!/usr/bin/env python3
"""Rebuild INDEX.json from card frontmatter. INDEX is derived; never edit it by hand."""
from __future__ import annotations

import argparse
import json
import sys
from datetime import date

import registry as R


def build(rd) -> dict:
    cards = R.load_cards(rd)
    return {
        "_note": "Derived artifact generated by build_index.py. The truth is in each "
                 "card's frontmatter; do not edit this file by hand.",
        "schema_version": R.load_schema(rd).get("schema_version"),
        "generated_on": date.today().isoformat(),
        "count": len(cards),
        "cards": [R.index_record(c) for c in cards],
    }


def write(rd) -> dict:
    idx = build(rd)
    (rd / "INDEX.json").write_text(json.dumps(idx, ensure_ascii=False, indent=2) + "\n",
                                   encoding="utf-8")
    return idx


def main(argv=None) -> int:
    R.utf8_stdio()
    ap = argparse.ArgumentParser(description=__doc__)
    R.add_registry_arg(ap)
    a = ap.parse_args(argv)
    rd = R.resolve_or_exit(a.registry)
    try:
        idx = write(rd)
    except R.CardError as e:
        print(f"error: cannot rebuild INDEX.json: {e}", file=sys.stderr)
        return 3
    print(f"Wrote {rd / 'INDEX.json'} -- {idx['count']} cards")
    return 0


if __name__ == "__main__":
    sys.exit(main())
